import { describe, expect, it, vi } from 'vitest';
import { bestCoverUrl, BookDetails, extractYear, GoogleBooksClient } from '../src/api/googlebooks';
import { HttpError, HttpRequest } from '../src/api/types';
import searchFixture from './fixtures/googlebooks_search.json';
import volumeFixture from './fixtures/googlebooks_volume.json';

// Generated by the Python CLI's GoogleBooksClient from the same fixtures
// (search, then details for the first result).
const CLI_DUNE_NOTE =
	'---\ncollection: "[[Books]]"\ntags:\n  - fiction\n  - sci-fi\n---\n\n## Links\nhttps://books.google.com/books/about/Dune.html?id=B1hSG45JCX4C\n\n## Description\nSet on the desert planet Arrakis, Dune is the story of Paul Atreides.\n\nBy [[Frank Herbert]].\n';
const COVER =
	'https://books.google.com/books/content?id=B1hSG45JCX4C&printsec=frontcover&img=1&zoom=1&source=gbs_api';

function setup(...responses: unknown[]) {
	const request = vi.fn<(req: HttpRequest) => Promise<unknown>>();
	for (const r of responses) {
		if (r instanceof Error) request.mockRejectedValueOnce(r);
		else request.mockResolvedValueOnce(r);
	}
	const sleep = vi.fn((_ms: number) => Promise.resolve());
	return { client: new GoogleBooksClient('KEY', request, sleep), request, sleep };
}

describe('GoogleBooksClient.search', () => {
	it('sends the key and country, and groups editions by title and author', async () => {
		const { client, request } = setup(searchFixture);
		const results = await client.search('Dune');

		const url = new URL(request.mock.calls[0]?.[0].url ?? '');
		expect(url.origin + url.pathname).toBe('https://www.googleapis.com/books/v1/volumes');
		expect(Object.fromEntries(url.searchParams)).toEqual({
			key: 'KEY',
			country: 'US',
			q: 'intitle:Dune',
			maxResults: '25',
			printType: 'books',
		});

		expect(results).toEqual([
			{
				id: 'B1hSG45JCX4C',
				title: 'Dune',
				year: '1990',
				overview: 'Frank Herbert',
				thumbnailUrl:
					'https://books.google.com/books/content?id=B1hSG45JCX4C&printsec=frontcover&img=1&zoom=5&source=gbs_api',
			},
			{ id: 'dune_messiah_id', title: 'Dune Messiah', year: '1969', overview: 'Frank Herbert', thumbnailUrl: null },
		]);
	});

	it('reports the earliest year across editions', async () => {
		const editions = [
			{ id: 'later', volumeInfo: { title: 'Dune', authors: ['Frank Herbert'], publishedDate: '2005' } },
			{ id: 'first', volumeInfo: { title: 'DUNE', authors: ['frank herbert'], publishedDate: '1965-08-01' } },
			{ id: 'none', volumeInfo: { title: 'Dune', authors: ['Frank Herbert'] } },
		];
		const { client } = setup({ items: editions }, { volumeInfo: { title: 'Dune', publishedDate: '2005' } });
		const results = await client.search('Dune');
		expect(results.map((r) => [r.id, r.year])).toEqual([['later', '1965']]);
		// The details for the stand-in edition use that earliest year.
		expect((await client.getDetails('later')).firstPublishYear).toBe(1965);
	});

	it('handles no items', async () => {
		const { client } = setup({ items: null });
		expect(await client.search('zzz')).toEqual([]);
	});

	it('retries transient errors with backoff', async () => {
		const { client, request, sleep } = setup(
			new HttpError(503, 'Request failed with status 503'),
			new HttpError(null, 'Network error'),
			searchFixture,
		);
		expect(await client.search('Dune')).toHaveLength(2);
		expect(request).toHaveBeenCalledTimes(3);
		expect(sleep.mock.calls).toEqual([[500], [1000]]);
	});

	it('gives up after three retries', async () => {
		const err = new HttpError(429, 'Request failed with status 429');
		const { client, request } = setup(err, err, err, err);
		await expect(client.search('Dune')).rejects.toThrow('Google Books API error: Request failed with status 429');
		expect(request).toHaveBeenCalledTimes(4);
	});

	it('does not retry a bad key', async () => {
		const { client, request, sleep } = setup(new HttpError(400, 'Request failed with status 400'));
		await expect(client.search('Dune')).rejects.toThrow('status 400');
		expect(request).toHaveBeenCalledTimes(1);
		expect(sleep).not.toHaveBeenCalled();
	});
});

describe('GoogleBooksClient.getDetails', () => {
	it('matches the CLI after a search', async () => {
		const { client, request } = setup(searchFixture, volumeFixture);
		await client.search('Dune');
		const details = await client.getDetails('B1hSG45JCX4C');
		expect(new URL(request.mock.calls[1]?.[0].url ?? '').pathname).toBe('/books/v1/volumes/B1hSG45JCX4C');
		expect(details).toEqual({
			id: 'B1hSG45JCX4C',
			title: 'Dune',
			author: 'Frank Herbert',
			description: 'Set on the desert planet Arrakis, Dune is the story of Paul Atreides.',
			subjects: ['Fiction', 'Science Fiction'],
			firstPublishYear: 1990,
			coverUrl: COVER,
			infoLink: 'https://books.google.com/books/about/Dune.html?id=B1hSG45JCX4C',
		});
		expect(client.formatNote(details)).toBe(CLI_DUNE_NOTE);
		expect(client.getFilename(details)).toBe('Frank Herbert - Dune (1990).md');
		expect(client.getPosterUrl(details)).toBe(COVER);
	});

	it('uses the volume date outside a search', async () => {
		const { client } = setup(volumeFixture);
		expect((await client.getDetails('B1hSG45JCX4C')).firstPublishYear).toBe(1990);
	});
});

describe('Google Books helpers and notes', () => {
	const { client } = setup();
	const bare: BookDetails = {
		id: 'x',
		title: 'Untitled: A Draft',
		author: 'Unknown',
		description: '',
		subjects: [],
		firstPublishYear: null,
		coverUrl: null,
		infoLink: '',
	};

	it('writes a note with no description, link or year', () => {
		expect(client.formatNote(bare)).toBe(
			'---\ncollection: "[[Books]]"\n---\n\n## Links\nNot available\n\n## Description\nBy [[Unknown]].\n',
		);
		expect(client.getFilename(bare)).toBe('Unknown - Untitled - A Draft (TBD).md');
		expect(client.getTitleAndYear(bare)).toEqual({ title: 'Untitled: A Draft', year: null });
	});

	it.each([
		['1990-09', 1990],
		['c. 1847', 1847],
		['', null],
		[undefined, null],
		['12345', null],
	])('extracts the year from %j', (text, year) => {
		expect(extractYear(text)).toBe(year);
	});

	it('picks the largest cover over HTTPS without the page curl', () => {
		expect(
			bestCoverUrl({ thumbnail: 'http://x/t?a=1&edge=curl', large: 'http://x/l?a=1&edge=curl' }),
		).toBe('https://x/l?a=1');
		expect(bestCoverUrl(undefined)).toBeNull();
		expect(bestCoverUrl({})).toBeNull();
	});
});
